from dataclasses import dataclass
from typing import Optional

@dataclass
class OrderResult:
    order_id: int
    total: float
    user_id: int

def _validate_order(order: dict) -> Optional[str]:
    if order is None:
        return 'order is None'
    if order.get('status') != 'pending':
        return f'invalid status: {order.get("status")}'
    if not order.get('items'):
        return 'order has no items'
    if order.get('user_id') is None:
        return 'missing user_id'
    for i, item in enumerate(order['items']):
        if item.get('price') is None:
            return f'item {i} missing price'
        if item.get('quantity') is None:
            return f'item {i} missing quantity'
    return None

def process_order(order: dict) -> Optional[OrderResult]:
    error = _validate_order(order)
    if error:
        return None
    total = sum(item['price'] * item['quantity'] for item in order['items'])
    return OrderResult(order_id=order['id'], total=total, user_id=order['user_id'])

