def calculate_discount(price, user_type, is_member, years_active):
    discount = 0
    if user_type == 'student':
        discount = 0.2
        if is_member:
            discount = 0.25
            if years_active > 5:
                discount = 0.3
    elif user_type == 'senior':
        discount = 0.15
        if is_member:
            discount = 0.2
            if years_active > 5:
                discount = 0.25
    elif user_type == 'regular':
        discount = 0.0
        if is_member:
            discount = 0.1
            if years_active > 5:
                discount = 0.15
    return price * (1 - discount)

