class Pipeline:
    def __init__(self, data):
        self.data = data

    def run(self):
        # Step 1: filter nulls
        step1 = []
        for item in self.data:
            if item is not None:
                step1.append(item)

        # Step 2: normalize strings
        step2 = []
        for item in step1:
            step2.append(item.strip().lower() if isinstance(item, str) else item)

        # Step 3: deduplicate
        step3 = []
        seen = set()
        for item in step2:
            if item not in seen:
                seen.add(item)
                step3.append(item)

        # Step 4: sort
        return sorted(step3)

