from typing import Callable

def pipe(*funcs: Callable) -> Callable:
    def _pipe(data):
        for fn in funcs:
            data = fn(data)
        return data
    return _pipe

def filter_nulls(data):
    return [x for x in data if x is not None]

def normalize_strings(data):
    return [x.strip().lower() if isinstance(x, str) else x for x in data]

def deduplicate(data):
    seen = set()
    result = []
    for item in data:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def sort_items(data):
    return sorted(data)

class Pipeline:
    def __init__(self, data):
        self.data = data
        self._run = pipe(filter_nulls, normalize_strings, deduplicate, sort_items)

    def run(self):
        return self._run(self.data)

