from dataclasses import dataclass
from typing import Optional

@dataclass(frozen=True)
class DiscountCode:
    code: str
    rate: float

DISCOUNT_CODES: dict[str, DiscountCode] = {
    'SAVE10':  DiscountCode('SAVE10',  0.10),
    'SAVE20':  DiscountCode('SAVE20',  0.20),
    'HALFOFF': DiscountCode('HALFOFF', 0.50),
}

TAX_RATE = 0.08

class Cart:
    def __init__(self):
        self.items: list[dict] = []
        self._discount_code: Optional[DiscountCode] = None

    def add_item(self, name: str, price: float, qty: int) -> None:
        self.items.append({'name': name, 'price': price, 'qty': qty})

    def apply_discount(self, code: str) -> None:
        if code not in DISCOUNT_CODES:
            raise ValueError(f'Unknown discount code: {code}')
        self._discount_code = DISCOUNT_CODES[code]

    @property
    def subtotal(self) -> float:
        return sum(i['price'] * i['qty'] for i in self.items)

    @property
    def discount(self) -> float:
        return 0.0 if self._discount_code is None else self.subtotal * self._discount_code.rate

    @property
    def tax(self) -> float:
        return (self.subtotal - self.discount) * TAX_RATE

    @property
    def total(self) -> float:
        return self.subtotal - self.discount + self.tax

