def process(data, operation, extra=None):
    if operation == 'filter':
        result = []
        for item in data:
            if extra and item.get(extra['field']) == extra['value']:
                result.append(item)
        return result
    elif operation == 'sort':
        key = extra.get('key') if extra else None
        reverse = extra.get('reverse', False) if extra else False
        return sorted(data, key=lambda x: x.get(key), reverse=reverse)
    elif operation == 'group':
        groups = {}
        field = extra.get('field') if extra else None
        for item in data:
            k = item.get(field)
            if k not in groups:
                groups[k] = []
            groups[k].append(item)
        return groups
    elif operation == 'aggregate':
        field = extra.get('field') if extra else None
        func = extra.get('func', 'sum') if extra else 'sum'
        values = [item.get(field, 0) for item in data]
        if func == 'sum': return sum(values)
        elif func == 'avg': return sum(values) / len(values) if values else 0
        elif func == 'min': return min(values) if values else None
        elif func == 'max': return max(values) if values else None
    raise ValueError(f'Unknown operation: {operation}')

output_expected:
from collections import defaultdict
from typing import Any

def filter_data(data: list[dict], field: str, value: Any) -> list[dict]:
    return [item for item in data if item.get(field) == value]

def sort_data(data: list[dict], key: str, reverse: bool = False) -> list[dict]:
    return sorted(data, key=lambda x: x.get(key), reverse=reverse)

def group_data(data: list[dict], field: str) -> dict[Any, list[dict]]:
    groups: dict = defaultdict(list)
    for item in data:
        groups[item.get(field)].append(item)
    return dict(groups)

_AGG_FUNCS = {
    'sum': sum,
    'avg': lambda vals: sum(vals) / len(vals) if vals else 0,
    'min': lambda vals: min(vals) if vals else None,
    'max': lambda vals: max(vals) if vals else None,
}

def aggregate_data(data: list[dict], field: str, func: str = 'sum') -> Any:
    if func not in _AGG_FUNCS:
        raise ValueError(f'Unknown aggregation function: {func}')
    return _AGG_FUNCS[func]([item.get(field, 0) for item in data])

class DataProcessor:
    def __init__(self, data: list[dict]):
        self.data = data

    def filter(self, field: str, value: Any) -> 'DataProcessor':
        return DataProcessor(filter_data(self.data, field, value))

    def sort(self, key: str, reverse: bool = False) -> 'DataProcessor':
        return DataProcessor(sort_data(self.data, key, reverse))

    def group(self, field: str) -> dict:
        return group_data(self.data, field)

    def aggregate(self, field: str, func: str = 'sum') -> Any:
        return aggregate_data(self.data, field, func)

    def to_list(self) -> list[dict]:
        return self.data

