    if not numbers:
        return {'count': 0, 'mean': 0.0, 'variance': 0.0, 'min': None, 'max': None}
    count = len(numbers)
    total = 0
    for n in numbers:
        total += n
    mean = total / count
    sq_diff_total = 0
    for n in numbers:
        sq_diff_total += (n - mean) ** 2
    variance = sq_diff_total / count
    return {
        'count': count,
        'mean': mean,
        'variance': variance,
        'min': min(numbers),
        'max': max(numbers),
    }

