def make_running_stats():
    data = {'count': 0, 'total': 0.0, 'sq_total': 0.0, 'min': None, 'max': None}

    def update(x):
        data['count'] += 1
        data['total'] += x
        data['sq_total'] += x * x
        if data['min'] is None or x < data['min']:
            data['min'] = x
        if data['max'] is None or x > data['max']:
            data['max'] = x

    def mean():
        return data['total'] / data['count'] if data['count'] else 0.0

    def variance():
        if data['count'] < 2:
            return 0.0
        m = mean()
        return data['sq_total'] / data['count'] - m * m

    def snapshot():
        return {'count': data['count'], 'mean': mean(), 'variance': variance(),
                'min': data['min'], 'max': data['max']}

    return update, snapshot

