from dataclasses import dataclass, field
from typing import Optional

@dataclass
class RunningStats:
    _count: int = field(default=0, init=False)
    _total: float = field(default=0.0, init=False)
    _sq_total: float = field(default=0.0, init=False)
    _min: Optional[float] = field(default=None, init=False)
    _max: Optional[float] = field(default=None, init=False)

    def update(self, x: float) -> None:
        self._count += 1
        self._total += x
        self._sq_total += x * x
        self._min = x if self._min is None else min(self._min, x)
        self._max = x if self._max is None else max(self._max, x)

    @property
    def mean(self) -> float:
        return self._total / self._count if self._count else 0.0

    @property
    def variance(self) -> float:
        if self._count < 2:
            return 0.0
        return self._sq_total / self._count - self.mean ** 2

    def snapshot(self) -> dict:
        return {
            'count': self._count,
            'mean': self.mean,
            'variance': self.variance,
            'min': self._min,
            'max': self._max,
        }

original_code:
def serialize(value):
    if isinstance(value, bool):
        return 'true' if value else 'false'
    elif isinstance(value, int):
        return str(value)
    elif isinstance(value, float):
        return f'{value:.6g}'
    elif isinstance(value, str):
        return f'"{value}"'
    elif isinstance(value, list):
        return '[' + ', '.join(serialize(v) for v in value) + ']'
    elif isinstance(value, dict):
        pairs = ', '.join(f'{serialize(k)}: {serialize(v)}' for k, v in value.items())
        return '{' + pairs + '}'
    elif value is None:
        return 'null'
    else:
        raise TypeError(f'Unsupported type: {type(value)}')

